    const table = document.querySelector(".table-wrap");

    filter.addEventListener("change", () => {
      const selected = filter.value;
      let visible = 0;

      rows.forEach((row) => {
        const show = selected === "all" || row.dataset.period === selected;
        row.hidden = !show;
        if (show) visible++;
